// sanity-login-fix.test.js
const request = require('supertest');
const app = require('../app'); // Express app

describe('Sanity Tests: Login Special Characters Fix', () => {
  // Test the specific bug scenario
  test('should login with special characters in password', async () => {
    const response = await request(app)
      .post('/api/login')
      .send({ 
        username: 'testuser', 
        password: 'pass@word123#' // Previously failing password
      });

    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('token');
    expect(response.body.user.username).toBe('testuser');
  });

  // Regression test: normal passwords still work
  test('should still login with normal password', async () => {
    const response = await request(app)
      .post('/api/login')
      .send({ 
        username: 'testuser', 
        password: 'normalpass' 
      });

    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('token');
  });

  // Edge case testing
  test('should handle various special characters', async () => {
    const testCases = [
      'test!@#$%^&*()',
      'password with spaces',
      'unicode-ñáéîø',
      'very-long-password-with-special-chars!@#'
    ];

    for (const password of testCases) {
      const response = await request(app)
        .post('/api/login')
        .send({ username: 'testuser', password });

      expect(response.status).toBe(200);
    }
  });

  // Security regression check
  test('should still prevent SQL injection attempts', async () => {
    const response = await request(app)
      .post('/api/login')
      .send({ 
        username: 'testuser', 
        password: "' OR '1'='1' --" // SQL injection attempt
      });

    expect(response.status).toBe(401); // Should still be unauthorized
  });
});

