// test-selector.js
const fs = require('fs');
const path = require('path');

class TestSelector {
  constructor() {
    this.testMapping = {
      'src/auth/': ['sanity-auth', 'sanity-login'],
      'src/payment/': ['sanity-payment', 'sanity-checkout'],
      'src/api/reports/': ['sanity-reporting', 'sanity-export'],
      'src/components/UserProfile/': ['sanity-profile', 'sanity-settings']
    };
  }

  getTestsForChangedFiles(changedFiles) {
    const testsToRun = new Set();

    changedFiles.forEach(file => {
      for (const [pathPattern, testSuites] of Object.entries(this.testMapping)) {
        if (file.includes(pathPattern)) {
          testSuites.forEach(test => testsToRun.add(test));
        }
      }
    });

    return Array.from(testsToRun);
  }

  // Additional logic for dependency analysis
  getDependentTests(mainTests) {
    const dependencies = {
      'sanity-checkout': ['sanity-payment', 'sanity-cart'],
      'sanity-reporting': ['sanity-data-export']
    };

    const allTests = new Set(mainTests);

    mainTests.forEach(test => {
      if (dependencies[test]) {
        dependencies[test].forEach(dep => allTests.add(dep));
      }
    });

    return Array.from(allTests);
  }
}

// Usage:
const selector = new TestSelector();
const changedFiles = ['src/auth/login.service.js', 'src/components/UserProfile/Profile.js'];
const tests = selector.getTestsForChangedFiles(changedFiles);
console.log('Tests to run:', tests);

// Output: ['sanity-auth', 'sanity-login', 'sanity-profile', 'sanity-settings']

