// Comprehensive database component test with migrations and transactions
import { GenericContainer, StartedTestContainer } from 'testcontainers';
import { Pool } from 'pg';

interface TestUser {
  id: string;
  email: string;
  name: string;
  status: 'active' | 'inactive';
}

class UserRepository {
  constructor(private pool: Pool) {}

  async createUser(user: Omit<TestUser, 'id'>): Promise<TestUser> {
    const result = await this.pool.query(
      `INSERT INTO users (email, name, status) VALUES ($1, $2, $3) 
       RETURNING id, email, name, status`,
      [user.email, user.name, user.status]
    );
    return result.rows[0];
  }

  async findUserById(id: string): Promise<TestUser | null> {
    const result = await this.pool.query(
      'SELECT id, email, name, status FROM users WHERE id = $1',
      [id]
    );
    return result.rows[0] || null;
  }

  async updateUserStatus(id: string, status: TestUser['status']): Promise<void> {
    await this.pool.query(
      'UPDATE users SET status = $1 WHERE id = $2',
      [status, id]
    );
  }
}

describe('UserRepository Component', () => {
  let container: StartedTestContainer;
  let pool: Pool;
  let repository: UserRepository;

  beforeAll(async () => {
    // Start PostgreSQL container with specific configuration
    container = await new GenericContainer('postgres:13-alpine')
      .withExposedPorts(5432)
      .withEnvironment({
        POSTGRES_DB: 'testdb',
        POSTGRES_USER: 'testuser',
        POSTGRES_PASSWORD: 'testpass',
        POSTGRES_HOST_AUTH_METHOD: 'trust'
      })
      .withTmpFs({ '/var/lib/postgresql/data': 'rw,noexec' }) // RAM disk for performance
      .start();

    const connectionConfig = {
      host: container.getHost(),
      port: container.getMappedPort(5432),
      database: 'testdb',
      user: 'testuser',
      password: 'testpass'
    };

    pool = new Pool(connectionConfig);

    // Run migrations
    await pool.query(`
      CREATE TABLE users (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        email VARCHAR(255) UNIQUE NOT NULL,
        name VARCHAR(255) NOT NULL,
        status VARCHAR(20) NOT NULL CHECK (status IN ('active', 'inactive')),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );

      CREATE INDEX idx_users_email ON users(email);
      CREATE INDEX idx_users_status ON users(status);
    `);

    repository = new UserRepository(pool);
  }, 30000); // 30 second timeout

  afterAll(async () => {
    if (pool) await pool.end();
    if (container) await container.stop();
  });

  beforeEach(async () => {
    // Clean data before each test
    await pool.query('TRUNCATE TABLE users RESTART IDENTITY CASCADE');
  });

  test('should create and retrieve user successfully', async () => {
    const userData = {
      email: 'test@example.com',
      name: 'Test User',
      status: 'active' as const
    };

    const createdUser = await repository.createUser(userData);

    expect(createdUser).toMatchObject({
      email: userData.email,
      name: userData.name,
      status: userData.status
    });
    expect(createdUser.id).toMatch(/^[0-9a-f-]{36}$/); // UUID format

    const retrievedUser = await repository.findUserById(createdUser.id);
    expect(retrievedUser).toEqual(createdUser);
  });

  test('should handle concurrent user creation', async () => {
    const userData = {
      email: 'concurrent@example.com',
      name: 'Concurrent User',
      status: 'active' as const
    };

    // Simulate concurrent creation attempts
    const results = await Promise.allSettled([
      repository.createUser(userData),
      repository.createUser(userData) // Duplicate email
    ]);

    const successful = results.filter(r => r.status === 'fulfilled');
    const failed = results.filter(r => r.status === 'rejected');

    expect(successful).toHaveLength(1);
    expect(failed).toHaveLength(1);

    if (failed[0].status === 'rejected') {
      expect(failed[0].reason.code).toBe('23505'); // Unique violation
    }
  });

  test('should update user status transactionally', async () => {
    const user = await repository.createUser({
      email: 'update@example.com',
      name: 'Update Test',
      status: 'active'
    });

    await repository.updateUserStatus(user.id, 'inactive');

    const updatedUser = await repository.findUserById(user.id);
    expect(updatedUser?.status).toBe('inactive');
  });
});

// Event-driven component testing with Apache Kafka
import { GenericContainer, StartedTestContainer } from 'testcontainers';
import { Kafka, Producer, Consumer, KafkaMessage } from 'kafkajs';

interface UserEvent {
  type: 'USER_CREATED' | 'USER_UPDATED' | 'USER_DELETED';
  userId: string;
  timestamp: string;
  payload: any;
}

class UserEventProducer {
  constructor(private producer: Producer, private topic: string) {}

  async sendUserEvent(event: Omit<UserEvent, 'timestamp'>): Promise<void> {
    await this.producer.send({
      topic: this.topic,
      messages: [{
        key: event.userId,
        value: JSON.stringify({
          ...event,
          timestamp: new Date().toISOString()
        })
      }]
    });
  }
}

class UserEventConsumer {
  private receivedEvents: UserEvent[] = [];

  constructor(private consumer: Consumer, private topic: string) {}

  async start(): Promise<void> {
    await this.consumer.subscribe({ topic: this.topic, fromBeginning: true });

    await this.consumer.run({
      eachMessage: async ({ message }) => {
        if (message.value) {
          const event = JSON.parse(message.value.toString()) as UserEvent;
          this.receivedEvents.push(event);
        }
      }
    });
  }

  getEvents(): UserEvent[] {
    return [...this.receivedEvents];
  }

  clearEvents(): void {
    this.receivedEvents = [];
  }
}

describe('Event-Driven Components', () => {
  let kafkaContainer: StartedTestContainer;
  let kafka: Kafka;
  let producer: UserEventProducer;
  let consumer: UserEventConsumer;
  const topic = 'user-events-test';

  beforeAll(async () => {
    // Start Kafka container with ZooKeeper
    kafkaContainer = await new GenericContainer('confluentinc/cp-kafka:6.2.0')
      .withExposedPorts(9092, 9093)
      .withEnvironment({
        KAFKA_ZOOKEEPER_CONNECT: 'localhost:2181',
        KAFKA_ADVERTISED_LISTENERS: 'PLAINTEXT://localhost:9092',
        KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR: '1'
      })
      .start();

    const kafkaHost = kafkaContainer.getHost();
    const kafkaPort = kafkaContainer.getMappedPort(9092);

    kafka = new Kafka({
      clientId: 'test-client',
      brokers: [`${kafkaHost}:${kafkaPort}`]
    });

    // Create topic
    const admin = kafka.admin();
    await admin.connect();
    await admin.createTopics({
      topics: [{
        topic,
        numPartitions: 1,
        replicationFactor: 1
      }]
    });
    await admin.disconnect();

    // Initialize producer and consumer
    const kafkaProducer = kafka.producer();
    await kafkaProducer.connect();

    const kafkaConsumer = kafka.consumer({ groupId: 'test-group' });
    await kafkaConsumer.connect();

    producer = new UserEventProducer(kafkaProducer, topic);
    consumer = new UserEventConsumer(kafkaConsumer, topic);
    await consumer.start();
  }, 60000); // 60 second timeout for Kafka setup

  afterAll(async () => {
    if (kafkaContainer) await kafkaContainer.stop();
  });

  beforeEach(() => {
    consumer.clearEvents();
  });

  test('should produce and consume user events', async () => {
    const testEvent: Omit<UserEvent, 'timestamp'> = {
      type: 'USER_CREATED',
      userId: 'user-123',
      payload: { name: 'Test User', email: 'test@example.com' }
    };

    await producer.sendUserEvent(testEvent);

    // Wait for event to be processed
    await new Promise(resolve => setTimeout(resolve, 2000));

    const events = consumer.getEvents();
    expect(events).toHaveLength(1);

    const receivedEvent = events[0];
    expect(receivedEvent.type).toBe('USER_CREATED');
    expect(receivedEvent.userId).toBe('user-123');
    expect(receivedEvent.payload).toEqual(testEvent.payload);
    expect(receivedEvent.timestamp).toBeDefined();
  });

  test('should handle multiple events in order', async () => {
    const events: Array<Omit<UserEvent, 'timestamp'>> = [
      {
        type: 'USER_CREATED',
        userId: 'user-1',
        payload: { name: 'User One' }
      },
      {
        type: 'USER_UPDATED',
        userId: 'user-1',
        payload: { name: 'User One Updated' }
      },
      {
        type: 'USER_CREATED',
        userId: 'user-2',
        payload: { name: 'User Two' }
      }
    ];

    for (const event of events) {
      await producer.sendUserEvent(event);
    }

    await new Promise(resolve => setTimeout(resolve, 3000));

    const receivedEvents = consumer.getEvents();
    expect(receivedEvents).toHaveLength(3);

    // Verify order for same partition key
    const user1Events = receivedEvents.filter(e => e.userId === 'user-1');
    expect(user1Events[0].type).toBe('USER_CREATED');
    expect(user1Events[1].type).toBe('USER_UPDATED');
  });
});

