      await cartPage.navigate();
      await cartPage.verifyProductDetails(productToPurchase);
      await cartPage.proceedToCheckout();
    });

    await test.step('Checkout process', async () => {
      await checkoutPage.enterShippingAddress(shippingInfo);
      await checkoutPage.selectShippingMethod('express');
      await checkoutPage.enterPaymentInformation(paymentInfo);
      await checkoutPage.placeOrder();
    });

    await test.step('Order confirmation', async () => {
      await confirmationPage.verifyOrderSuccess();
      const orderNumber = await confirmationPage.getOrderNumber();
      expect(orderNumber).toMatch(/ORD\d{8}/);

      // Verify order details in database
      const orderDetails = await confirmationPage.getOrderDetailsFromAPI(orderNumber);
      expect(orderDetails.status).toBe('confirmed');
      expect(orderDetails.totalAmount).toBeGreaterThan(0);
    });

    await test.step('Post-purchase validation', async () => {
