});

// API-driven E2E workflow testing
const { apiClient } = require('../utils/apiClient');
const { dataGenerator } = require('../utils/dataGenerator');
const { validator } = require('../utils/validator');

describe('API-Driven Order Management Workflow', () => {
  let authToken;
  let customerId;
  let productId;
  let orderId;

  beforeAll(async () => {
    // Setup test data
    const customerData = dataGenerator.createCustomer();
    const productData = dataGenerator.createProduct();

    // Create test entities
    customerId = await apiClient.createCustomer(customerData);
    productId = await apiClient.createProduct(productData);

    // Authenticate
    authToken = await apiClient.authenticate({
      username: process.env.TEST_USER,
      password: process.env.TEST_PASSWORD
    });
  });

  test('should complete order lifecycle via API', async () => {
    // Phase 1: Order Creation
    const orderPayload = {
      customerId: customerId,
      items: [{
        productId: productId,
        quantity: 2,
        unitPrice: 29.99
      }],
      shippingAddress: dataGenerator.createAddress()
    };

    const createResponse = await apiClient.createOrder(orderPayload, authToken);
    orderId = createResponse.orderId;

    await validator.validateOrderCreation(createResponse, orderPayload);

    // Phase 2: Payment Processing
    const paymentPayload = {
      orderId: orderId,
      paymentMethod: 'credit_card',
      cardDetails: {
        number: '4111111111111111',
        expiry: '12/25',
        cvv: '123'
      }
    };

    const paymentResponse = await apiClient.processPayment(paymentPayload, authToken);
    await validator.validatePaymentProcessing(paymentResponse);

    // Phase 3: Order Fulfillment
    const fulfillmentResponse = await apiClient.fulfillOrder(orderId, authToken);
    await validator.validateOrderFulfillment(fulfillmentResponse);

    // Phase 4: Shipping Validation
    const shippingResponse = await apiClient.getShippingDetails(orderId, authToken);
    await validator.validateShippingDetails(shippingResponse);

    // Phase 5: Delivery Confirmation
    const deliveryPayload = {
      orderId: orderId,
      status: 'delivered',
      deliveryDate: new Date().toISOString()
    };

    const deliveryResponse = await apiClient.confirmDelivery(deliveryPayload, authToken);
    await validator.validateDeliveryConfirmation(deliveryResponse);

    // Phase 6: End-to-End Validation
    const finalOrderState = await apiClient.getOrder(orderId, authToken);
    await validator.validateCompleteOrderLifecycle(finalOrderState);

    // Verify side effects and integrations
    await test.step('Validate inventory update', async () => {
      const inventory = await apiClient.getInventory(productId, authToken);
      expect(inventory.currentStock).toBeLessThan(inventory.initialStock);
    });

    await test.step('Validate accounting integration', async () => {
      const accountingRecord = await apiClient.getAccountingEntry(orderId, authToken);
      expect(accountingRecord.status).toBe('posted');
      expect(accountingRecord.amount).toBe(59.98);
    });

    await test.step('Validate customer notification', async () => {
      const notifications = await apiClient.getCustomerNotifications(customerId, authToken);
      const orderNotification = notifications.find(n => n.type === 'order_delivered');
      expect(orderNotification).toBeDefined();
      expect(orderNotification.orderId).toBe(orderId);
    });
  });

  test('should handle order cancellation workflow', async () => {
    // Test cancellation scenario
    const orderPayload = {
      customerId: customerId,
      items: [{ productId: productId, quantity: 1, unitPrice: 29.99 }],
      shippingAddress: dataGenerator.createAddress()
    };

    const orderResponse = await apiClient.createOrder(orderPayload, authToken);
    const cancelResponse = await apiClient.cancelOrder(orderResponse.orderId, authToken);

    await validator.validateOrderCancellation(cancelResponse);

    // Verify cancellation side effects
    const refund = await apiClient.getRefundDetails(orderResponse.orderId, authToken);
    expect(refund.status).toBe('processed');

    const inventory = await apiClient.getInventory(productId, authToken);
    expect(inventory.currentStock).toBe(inventory.initialStock); // Stock should be restored
  });
});

