// Secure: server checks authenticated user's role from session/DB
function requireAdmin(req, res, next) {
  if (req.user && req.user.role === 'admin') return next();
  return res.status(403).send('Forbidden');
}
app.post('/admin/createUser', requireAdmin, (req, res) => {
  const { username } = req.body;
  db.query('INSERT INTO users (username) VALUES (?)', [username]);
  res.send('created');
});

// Unsafe: trusting JWT claims without verifying signature
const claims = jwt.decode(token);
if (claims.role === 'admin') { /* grant admin */ }

// Safe: verify signature and validate claims
try {
  const payload = jwt.verify(token, process.env.JWT_SECRET);
  if (payload.role === 'admin') { /* grant admin */ }
} catch (err) {
  // invalid token
}

