public class CSVReader {
    public static List<String[]> readCSV(String path) throws Exception {
        BufferedReader br = new BufferedReader(new FileReader(path));
        String line;
        List<String[]> data = new ArrayList<>();
        while ((line = br.readLine()) != null) {
