// SecurityTestBase.cs
using System.Security.Cryptography;
using System.Text;
using OpenQA.Selenium;

namespace Tests.Security
{
    public interface ISecurityTester
    {
        Task<bool> CheckForSqlInjectionVulnerability(string inputFieldId, string payload);
        Task<bool> CheckForXssVulnerability(string inputFieldId, string payload);
        Task<bool> VerifySslCertificate(string url);
        Task<bool> CheckForInformationDisclosure(string url);
        void VerifySecurityHeaders(HttpResponseMessage response);
        Task<bool> TestAuthenticationBypass(string protectedUrl);
    }

    public class SecurityTester : ISecurityTester
    {
        private readonly IWebDriver _driver;
        private readonly HttpClient _httpClient;

        public SecurityTester(IWebDriver driver)
        {
            _driver = driver;
            _httpClient = new HttpClient();
        }

        public async Task<bool> CheckForSqlInjectionVulnerability(string inputFieldId, string payload)
        {
            try
            {
                // SQL Injection test payloads
                var sqlPayloads = new[]
                {
                    "' OR '1'='1",
                    "; DROP TABLE users --",
                    "' UNION SELECT username, password FROM users --"
                };

                foreach (var sqlPayload in sqlPayloads)
                {
                    var inputElement = _driver.FindElement(By.Id(inputFieldId));
                    inputElement.Clear();
                    inputElement.SendKeys(sqlPayload);

                    // Submit form or trigger action
                    inputElement.SendKeys(Keys.Enter);

                    // Check for error messages or unexpected behavior
                    var pageSource = _driver.PageSource.ToLower();

                    if (pageSource.Contains("sql") || pageSource.Contains("database") || 
                        pageSource.Contains("error") || pageSource.Contains("exception"))
                    {
                        return true; // Potential vulnerability found
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"SQL Injection test failed: {ex.Message}");
                return false;
            }
        }

        public async Task<bool> CheckForXssVulnerability(string inputFieldId, string payload)
        {
            try
            {
                // XSS test payloads
                var xssPayloads = new[]
                {
                    "<script>alert('XSS')</script>",
                    "<img src=x onerror=alert('XSS')>",
                    "javascript:alert('XSS')"
                };

                foreach (var xssPayload in xssPayloads)
                {
                    var inputElement = _driver.FindElement(By.Id(inputFieldId));
                    inputElement.Clear();
                    inputElement.SendKeys(xssPayload);

                    // Submit form
                    inputElement.SendKeys(Keys.Enter);

                    // Check if script executed
                    var pageSource = _driver.PageSource;

                    if (pageSource.Contains(xssPayload) && !pageSource.Contains("&lt;script&gt;"))
                    {
                        return true; // Potential XSS vulnerability
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"XSS test failed: {ex.Message}");
                return false;
            }
        }

        public async Task<bool> VerifySslCertificate(string url)
        {
            try
            {
                var handler = new HttpClientHandler
                {
                    ServerCertificateCustomValidationCallback = (message, cert, chain, errors) =>
                    {
                        // Check certificate validity
                        return errors == System.Net.Security.SslPolicyErrors.None &&
                               cert.Verify() &&
                               DateTime.Now >= cert.NotBefore &&
                               DateTime.Now <= cert.NotAfter;
                    }
                };

                using var client = new HttpClient(handler);
                var response = await client.GetAsync(url);

                return response.IsSuccessStatusCode;
            }
            catch
            {
                return false;
            }
        }

        public async Task<bool> CheckForInformationDisclosure(string url)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);
                var content = await response.Content.ReadAsStringAsync();

                // Check for sensitive information in response
                var sensitivePatterns = new[]
                {
                    "stack trace",
                    "internal server error",
                    "database connection",
                    "connection string",
                    "api key",
                    "password"
                };

                return sensitivePatterns.Any(pattern => 
                    content.ToLower().Contains(pattern.ToLower()));
            }
            catch
            {
                return false;
            }
        }

        public void VerifySecurityHeaders(HttpResponseMessage response)
        {
            var requiredHeaders = new Dictionary<string, string>
            {
                ["X-Content-Type-Options"] = "nosniff",
                ["X-Frame-Options"] = "DENY",
                ["X-XSS-Protection"] = "1; mode=block",
                ["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
            };

            foreach (var header in requiredHeaders)
            {
                if (response.Headers.TryGetValues(header.Key, out var values))
                {
                    values.First().Should().Be(header.Value, $"Security header {header.Key} should be set correctly");
                }
                else
                {
                    throw new Exception($"Missing security header: {header.Key}");
                }
            }
        }

        public async Task<bool> TestAuthenticationBypass(string protectedUrl)
        {
            try
            {
                // Try to access protected resource without authentication
                var response = await _httpClient.GetAsync(protectedUrl);

                // Should redirect to login or return 401/403
                return response.StatusCode == System.Net.HttpStatusCode.Redirect ||
                       response.StatusCode == System.Net.HttpStatusCode.Unauthorized ||
                       response.StatusCode == System.Net.HttpStatusCode.Forbidden;
            }
            catch
            {
                return false;
            }
        }
    }

    // Security-aware test scenarios
    public class SecurityAwareLoginTests
    {
        private readonly LoginPage _loginPage;
        private readonly ISecurityTester _securityTester;

        public SecurityAwareLoginTests(LoginPage loginPage, ISecurityTester securityTester)
        {
            _loginPage = loginPage;
            _securityTester = securityTester;
        }

        public async Task TestLoginSecurity()
        {
            // Test for SQL injection in username field
            var hasSqlInjection = await _securityTester.CheckForSqlInjectionVulnerability("username", "test");
            hasSqlInjection.Should().BeFalse("Login should be protected against SQL injection");

            // Test for XSS in username field
            var hasXss = await _securityTester.CheckForXssVulnerability("username", "test");
            hasXss.Should().BeFalse("Login should be protected against XSS");

            // Verify SSL certificate
            var hasValidSsl = await _securityTester.VerifySslCertificate(_loginPage.GetPageUrl());
            hasValidSsl.Should().BeTrue("Login page should use valid SSL certificate");

            // Test authentication bypass
            var isProtected = await _securityTester.TestAuthenticationBypass(_loginPage.GetDashboardUrl());
            isProtected.Should().BeTrue("Dashboard should require authentication");
        }
    }
}

