// Database-UI Integration Service
public interface IDatabaseUiIntegrationService
{
    Task<T> CreateTestDataInDatabase<T>(T entity) where T : class;
    Task VerifyDatabaseState<T>(string query, Action<T> assertions) where T : class;
    Task CleanupTestDataInDatabase(string tableName, string condition);
    Task<int> GetRecordCount(string tableName, string condition = "");
    Task<List<T>> QueryDatabase<T>(string sql, object parameters = null) where T : class;
}

public class DatabaseUiIntegrationService : IDatabaseUiIntegrationService
{
    private readonly IDatabaseTestBase _database;
    private readonly ITestLogger _logger;
    private readonly List<DatabaseCleanupAction> _cleanupActions;

    public DatabaseUiIntegrationService(IDatabaseTestBase database, ITestLogger logger)
    {
        _database = database;
        _logger = logger;
        _cleanupActions = new List<DatabaseCleanupAction>();
    }

    public async Task<T> CreateTestDataInDatabase<T>(T entity) where T : class
    {
        try
        {
            _logger.Info($"Creating test data in database: {typeof(T).Name}");

            // Use Dapper or Entity Framework to insert data
            var insertedId = await _database.InsertEntityAsync(entity);

            // Store cleanup action
            var cleanupAction = new DatabaseCleanupAction
            {
                TableName = GetTableName<T>(),
                Condition = $"{GetIdColumn<T>()} = {insertedId}",
                EntityType = typeof(T).Name
            };

            _cleanupActions.Add(cleanupAction);

            _logger.Info($"Test data created in database with ID: {insertedId}");

            // Return the entity with the generated ID
            return await SetEntityId(entity, insertedId);
        }
        catch (Exception ex)
        {
            _logger.Error($"Failed to create test data in database for {typeof(T).Name}", ex);
            throw;
        }
    }

    public async Task VerifyDatabaseState<T>(string query, Action<T> assertions) where T : class
    {
        try
        {
            _logger.Info($"Verifying database state with query: {query}");

            var results = await _database.QueryAsync<T>(query);

            if (results.Any())
            {
                assertions(results.First());
            }
            else
            {
                throw new InvalidOperationException("No results found for database verification");
            }

            _logger.Info("Database state verification completed successfully");
        }
        catch (Exception ex)
        {
            _logger.Error($"Database state verification failed for query: {query}", ex);
            throw;
        }
    }

    public async Task CleanupTestDataInDatabase(string tableName, string condition)
    {
        try
        {
            _logger.Info($"Cleaning up test data in {tableName} where {condition}");

            await _database.ExecuteAsync($"DELETE FROM {tableName} WHERE {condition}");

            _logger.Info("Test data cleanup completed successfully");
        }
        catch (Exception ex)
        {
            _logger.Warn($"Failed to cleanup test data in {tableName}", ex);
        }
    }

    public async Task<int> GetRecordCount(string tableName, string condition = "")
    {
        var sql = $"SELECT COUNT(*) FROM {tableName}";
        if (!string.IsNullOrEmpty(condition))
        {
            sql += $" WHERE {condition}";
        }

        return await _database.ExecuteScalarAsync<int>(sql);
    }

    public async Task<List<T>> QueryDatabase<T>(string sql, object parameters = null) where T : class
    {
        return await _database.QueryAsync<T>(sql, parameters);
    }

    public async Task CleanupAllTestData()
    {
        _logger.Info("Cleaning up all test data from database");

        foreach (var cleanupAction in _cleanupActions)
        {
            await CleanupTestDataInDatabase(cleanupAction.TableName, cleanupAction.Condition);
        }

        _cleanupActions.Clear();
    }

    private string GetTableName<T>()
    {
        // Implementation to get table name from type
        return typeof(T).Name + "s";
    }

    private string GetIdColumn<T>()
    {
        // Implementation to get ID column name from type
        return typeof(T).Name + "Id";
    }

    private async Task<T> SetEntityId<T>(T entity, object id) where T : class
    {
        // Implementation to set ID property on entity
        return entity;
    }
}

