import com.example.utilities.WebDriverManager;
import org.openqa.selenium.WebDriver;
import org.testng.Assert;
import org.testng.ITestResult;
import org.testng.annotations.*;

public class LoginTests {
    private WebDriver driver;
    private LoginPage loginPage;
    private DashboardPage dashboardPage;

    @BeforeMethod
    public void setUp() {
        driver = WebDriverManager.getDriver();
        driver.manage().window().maximize();
        driver.get(ConfigReader.getProperty("app.url"));
        loginPage = new LoginPage(driver);
    }

    @Test(priority = 1, description = "Verify successful login with valid credentials")
    public void testSuccessfulLogin() {
        // Test data
        String username = ConfigReader.getProperty("valid.username");
        String password = ConfigReader.getProperty("valid.password");

        // Perform login
        dashboardPage = loginPage.login(username, password);

        // Assertions
        Assert.assertTrue(dashboardPage.isDashboardLoaded(), 
            "Dashboard should be loaded after successful login");
        Assert.assertTrue(dashboardPage.getWelcomeMessage().contains("Welcome"),
            "Welcome message should be displayed");
    }

    @Test(priority = 2, description = "Verify login failure with invalid credentials")
    public void testInvalidLogin() {
        // Test data
        String username = "invaliduser";
        String password = "invalidpass";

        // Perform login with invalid credentials
        loginPage.loginWithInvalidCredentials(username, password);

        // Assertions
        Assert.assertTrue(loginPage.isErrorMessageDisplayed(),
            "Error message should be displayed for invalid login");
        Assert.assertEquals(loginPage.getErrorMessage(), 
            "Invalid username or password",
            "Error message text should match expected");
    }

    @Test(priority = 3, description = "Verify login with empty credentials")
    public void testLoginWithEmptyCredentials() {
        // Perform login with empty credentials
        loginPage.clickLogin();

        // Assertions
        Assert.assertTrue(loginPage.isErrorMessageDisplayed(),
            "Error message should be displayed for empty credentials");
    }

    @Test(priority = 4, dataProvider = "loginData")
    public void testDataDrivenLogin(String username, String password, boolean expectedSuccess) {
        if (expectedSuccess) {
            dashboardPage = loginPage.login(username, password);
            Assert.assertTrue(dashboardPage.isDashboardLoaded(),
                "Dashboard should be loaded for successful login");
        } else {
            loginPage.loginWithInvalidCredentials(username, password);
            Assert.assertTrue(loginPage.isErrorMessageDisplayed(),
                "Error message should be displayed for failed login");
        }
    }

    @DataProvider(name = "loginData")
    public Object[][] getLoginData() {
        return new Object[][] {
            {"admin", "admin123", true},
            {"user", "user123", true},
            {"wronguser", "wrongpass", false},
            {"", "", false}
        };
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        // Capture screenshot on failure
        if (result.getStatus() == ITestResult.FAILURE) {
            loginPage.takeScreenshot(result.getName());
        }

        if (driver != null) {
            driver.quit();
        }
    }
}

