// COMPREHENSIVE PIPELINE STRUCTURE - Java & Python Tests
pipeline {
    agent any

    options {
        timeout(time: 60, unit: 'MINUTES')
        disableConcurrentBuilds()
    }

    parameters {
        choice(
            name: 'LANGUAGE',
            choices: ['java', 'python', 'both'],
            description: 'Select test language'
        )
        booleanParam(
            name: 'RUN_PARALLEL',
            defaultValue: true,
            description: 'Execute tests in parallel'
        )
    }

    stages {
        stage('Environment Setup') {
            steps {
                echo 'Setting up test environment...'
                sh '''
                    echo "Java Version:"
                    java -version 2>&1 | head -n 3
                    echo "Python Version:"
                    python --version 2>&1
                    echo "Maven Version:"
                    mvn --version 2>&1 | head -n 3
                '''
            }
        }

        stage('Dependency Installation') {
            parallel {
                stage('Java Dependencies') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'java' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'mvn dependency:resolve'
                        sh 'mvn clean compile'
                    }
                }

                stage('Python Dependencies') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'python' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'pip install -r requirements.txt'
                        sh 'pip install -r test-requirements.txt'
                    }
                }
            }
        }

        stage('Test Execution') {
            when {
                expression { params.RUN_PARALLEL }
            }
            parallel {
                stage('Java Unit Tests') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'java' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'mvn test -Dtest=**/*UnitTest'
                    }
                }

                stage('Java Integration Tests') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'java' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'mvn test -Dtest=**/*IntegrationTest'
                    }
                }

                stage('Python Unit Tests') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'python' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'pytest tests/unit/ -v --junitxml=reports/python-unit-results.xml'
                    }
                }

                stage('Python API Tests') {
                    when {
                        anyOf {
                            expression { params.LANGUAGE == 'python' }
                            expression { params.LANGUAGE == 'both' }
                        }
                    }
                    steps {
                        sh 'pytest tests/api/ -v --junitxml=reports/python-api-results.xml'
                    }
                }
            }
        }

        stage('Sequential Test Execution') {
            when {
                expression { !params.RUN_PARALLEL }
            }
            steps {
                script {
                    if (params.LANGUAGE == 'java' || params.LANGUAGE == 'both') {
                        sh 'mvn test'
                    }
                    if (params.LANGUAGE == 'python' || params.LANGUAGE == 'both') {
                        sh 'pytest tests/ -v'
                    }
                }
            }
        }

        // Matrix builds for cross-platform testing
        stage('Cross-Browser Tests') {
            matrix {
                axes {
                    axis {
                        name 'BROWSER'
                        values 'chrome', 'firefox', 'edge'
                    }
                    axis {
                        name 'PLATFORM'
                        values 'windows', 'linux', 'macos'
                    }
                }
                stages {
                    stage('Browser Test') {
                        steps {
                            script {
                                echo "Testing on ${BROWSER} - ${PLATFORM}"
                                // Execute browser-specific tests
                                if (params.LANGUAGE == 'java' || params.LANGUAGE == 'both') {
                                    sh "mvn test -Dbrowser=${BROWSER} -Dplatform=${PLATFORM} -Dgroups=web"
                                }
                                if (params.LANGUAGE == 'python' || params.LANGUAGE == 'both') {
                                    sh "pytest tests/web/ -v --browser=${BROWSER} --platform=${PLATFORM}"
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    post {
        always {
            // Java test reports
            junit 'target/surefire-reports/**/*.xml'
            junit 'reports/**/*.xml'

            // Archive artifacts
            archiveArtifacts artifacts: 'target/**/*.png, reports/**/*.html', allowEmptyArchive: true

            // Cleanup
            sh 'mvn clean'
            sh 'rm -rf __pycache__ .pytest_cache'
        }

        success {
            emailext (
                subject: "SUCCESS: Multi-Language Test Build ${env.BUILD_NUMBER}",
                body: """
                <h2>Test Execution Completed Successfully</h2>
                <p><strong>Language:</strong> ${params.LANGUAGE}</p>
                <p><strong>Parallel Execution:</strong> ${params.RUN_PARALLEL}</p>
                <p><a href="${env.BUILD_URL}">View Build Details</a></p>
                """,
                to: 'qa-team@company.com'
            )
        }
    }
}

// ADVANCED ENVIRONMENT MANAGEMENT - Java & Python
pipeline {
    agent any

    // Global environment variables
    environment {
        // Java-specific environments
        JAVA_OPTS = '-Xmx2g -Xms512m'
        MAVEN_OPTS = '-Dmaven.repo.local=/tmp/m2repository'

        // Python-specific environments
        PYTHONPATH = '${WORKSPACE}/src:${WORKSPACE}/tests'
        PIP_CACHE_DIR = '/tmp/pip-cache'

        // Test configuration
        TEST_TIMEOUT = '300'
        LOG_LEVEL = 'INFO'

        // Derived environment variables
        BUILD_TIMESTAMP = new Date().format('yyyyMMdd-HHmmss')
        SHORT_COMMIT = sh(script: 'git rev-parse --short HEAD', returnStdout: true).trim()
    }

    // Extensive parameters for test configuration
    parameters {
        // Language selection
        choice(
            name: 'TEST_LANGUAGE',
            choices: ['java', 'python', 'both'],
            description: 'Primary test language'
        )

        // Environment selection
        choice(
            name: 'ENVIRONMENT',
            choices: ['dev', 'qa', 'staging', 'prod-like'],
            description: 'Target test environment'
        )

        // Test scope
        choice(
            name: 'TEST_SCOPE',
            choices: ['unit', 'integration', 'system', 'all'],
            description: 'Test scope to execute'
        )

        // Browser configuration
        choice(
            name: 'BROWSER',
            choices: ['chrome', 'firefox', 'edge', 'all'],
            description: 'Browser for UI tests'
        )

        // Parallel execution
        booleanParam(
            name: 'ENABLE_PARALLEL',
            defaultValue: true,
            description: 'Enable parallel test execution'
        )

        // Performance settings
        string(
            name: 'TEST_TIMEOUT',
            defaultValue: '300',
            description: 'Test execution timeout in seconds'
        )

        // Reporting options
        booleanParam(
            name: 'GENERATE_ALLURE',
            defaultValue: true,
            description: 'Generate Allure reports'
        )

        booleanParam(
            name: 'SEND_NOTIFICATIONS',
            defaultValue: true,
            description: 'Send email notifications'
        )
    }

    stages {
        stage('Dynamic Environment Setup') {
            steps {
                script {
                    // Set environment-specific variables
                    env.TEST_CONFIG_FILE = "config-${params.ENVIRONMENT}.properties"
                    env.REPORT_DIR = "reports/${params.ENVIRONMENT}/${BUILD_TIMESTAMP}"

                    // Browser configuration
                    if (params.BROWSER == 'all') {
                        env.BROWSERS = 'chrome,firefox,edge'
                    } else {
                        env.BROWSERS = params.BROWSER
                    }

                    // Log environment setup
                    echo "Environment: ${params.ENVIRONMENT}"
                    echo "Test Language: ${params.TEST_LANGUAGE}"
                    echo "Browser: ${env.BROWSERS}"
                    echo "Config File: ${env.TEST_CONFIG_FILE}"
                }

                // Create directories
                sh '''
                    mkdir -p ${REPORT_DIR}
                    mkdir -p logs
                    mkdir -p screenshots
                '''
            }
        }

        stage('Java Test Configuration') {
            when {
                anyOf {
                    expression { params.TEST_LANGUAGE == 'java' }
                    expression { params.TEST_LANGUAGE == 'both' }
                }
            }
            steps {
                script {
                    // Set Java-specific environment variables
                    env.JAVA_TEST_OPTS = "-Dconfig.file=${env.TEST_CONFIG_FILE} " +
                                       "-Dbrowser=${params.BROWSER} " +
                                       "-Dtimeout=${params.TEST_TIMEOUT} " +
                                       "-Dlog.level=${env.LOG_LEVEL}"

                    // Copy environment-specific config
                    sh "cp src/test/resources/${env.TEST_CONFIG_FILE} src/test/resources/config.properties"

                    echo "Java Test Options: ${env.JAVA_TEST_OPTS}"
                }
            }
        }

        stage('Python Test Configuration') {
            when {
                anyOf {
                    expression { params.TEST_LANGUAGE == 'python' }
                    expression { params.TEST_LANGUAGE == 'both' }
                }
            }
            steps {
                script {
                    // Set Python-specific environment variables
                    env.PYTEST_OPTS = "-v --tb=short --strict-markers " +
                                    "--junitxml=${env.REPORT_DIR}/python-results.xml " +
                                    "--html=${env.REPORT_DIR}/python-report.html " +
                                    "--self-contained-html"

                    if (params.ENABLE_PARALLEL) {
                        env.PYTEST_OPTS += " -n auto"
                    }

                    if (params.GENERATE_ALLURE) {
                        env.PYTEST_OPTS += " --alluredir=${env.REPORT_DIR}/allure-results"
                    }

                    echo "Pytest Options: ${env.PYTEST_OPTS}"
                }

                // Create Python config file
                sh '''
                    cat > test_config.ini << EOF
[environment]
name = ${ENVIRONMENT}
timeout = ${TEST_TIMEOUT}
log_level = ${LOG_LEVEL}

[browser]
name = ${BROWSER}
headless = true

[database]
host = db-${ENVIRONMENT}.company.com
port = 5432
EOF
                '''
            }
        }

        stage('Execute Tests with Dynamic Config') {
            steps {
                script {
                    // Java tests with dynamic configuration
                    if (params.TEST_LANGUAGE == 'java' || params.TEST_LANGUAGE == 'both') {
                        withEnv(["MAVEN_OPTS=${env.JAVA_TEST_OPTS}"]) {
                            switch(params.TEST_SCOPE) {
                                case 'unit':
                                    sh 'mvn test -Dtest=**/*Test'
                                    break
                                case 'integration':
                                    sh 'mvn test -Dgroups=integration'
                                    break
                                case 'system':
                                    sh 'mvn test -Dgroups=system'
                                    break
                                default:
                                    sh 'mvn test'
                            }
                        }
                    }

                    // Python tests with dynamic configuration
                    if (params.TEST_LANGUAGE == 'python' || params.TEST_LANGUAGE == 'both') {
                        withEnv(["PYTEST_OPTS=${env.PYTEST_OPTS}"]) {
                            switch(params.TEST_SCOPE) {
                                case 'unit':
                                    sh 'pytest tests/unit/ ${PYTEST_OPTS}'
                                    break
                                case 'integration':
                                    sh 'pytest tests/integration/ ${PYTEST_OPTS} -m integration'
                                    break
                                case 'system':
                                    sh 'pytest tests/system/ ${PYTEST_OPTS} -m system'
                                    break
                                default:
                                    sh 'pytest tests/ ${PYTEST_OPTS}'
                            }
                        }
                    }
                }
            }
        }
    }

    post {
        always {
            // Process test results
            junit '**/reports/**/*.xml'

            // Generate Allure reports if enabled
            script {
                if (params.GENERATE_ALLURE && fileExists("${env.REPORT_DIR}/allure-results")) {
                    allure([
                        includeProperties: false,
                        jdk: '',
                        properties: [],
                        reportBuildPolicy: 'ALWAYS',
                        results: [[path: "${env.REPORT_DIR}/allure-results"]]
                    ])
                }
            }

            // Send notifications if enabled
            script {
                if (params.SEND_NOTIFICATIONS) {
                    emailext (
                        subject: "${currentBuild.result ?: 'SUCCESS'}: Test Build ${env.BUILD_NUMBER}",
                        body: """
                        <h2>Test Execution Summary</h2>
                        <p><strong>Environment:</strong> ${params.ENVIRONMENT}</p>
                        <p><strong>Language:</strong> ${params.TEST_LANGUAGE}</p>
                        <p><strong>Scope:</strong> ${params.TEST_SCOPE}</p>
                        <p><strong>Status:</strong> ${currentBuild.result ?: 'SUCCESS'}</p>
                        <p><a href="${env.BUILD_URL}">View Build Details</a></p>
                        """,
                        to: 'qa-team@company.com'
                    )
                }
            }
        }
    }
}

// SHARED LIBRARY STRUCTURE
// vars/testUtils.groovy - Reusable test functions

/**
 * Execute Java tests with Maven
 */
def runJavaTests(Map params = [:]) {
    def defaults = [
        scope: 'all',
        environment: 'qa',
        parallel: true,
        timeout: '30m'
    ]

    def config = defaults + params

    echo "Executing Java tests with scope: ${config.scope}"

    // Set Maven options
    def mavenOpts = "-Denvironment=${config.environment} " +
                   "-Dtest.timeout=${config.timeout} " +
                   "-Dlog.level=INFO"

    if (config.parallel) {
        mavenOpts += " -Dparallel=true"
    }

    // Execute based on scope
    switch(config.scope) {
        case 'unit':
            sh "mvn test -Dtest=**/*Test ${mavenOpts}"
            break
        case 'integration':
            sh "mvn verify -Dgroups=integration ${mavenOpts}"
            break
        case 'regression':
            sh "mvn test -Dcucumber.filter.tags='@regression' ${mavenOpts}"
            break
        default:
            sh "mvn test ${mavenOpts}"
    }

    // Return test results path
    return 'target/surefire-reports'
}

/**
 * Execute Python tests with pytest
 */
def runPythonTests(Map params = [:]) {
    def defaults = [
        scope: 'all',
        environment: 'qa',
        parallel: true,
        markers: '',
        reportDir: 'reports'
    ]

    def config = defaults + params

    echo "Executing Python tests with scope: ${config.scope}"

    // Build pytest command
    def pytestCmd = "pytest "

    // Scope-specific test paths
    switch(config.scope) {
        case 'unit':
            pytestCmd += "tests/unit/ "
            break
        case 'integration':
            pytestCmd += "tests/integration/ "
            break
        case 'api':
            pytestCmd += "tests/api/ "
            break
        default:
            pytestCmd += "tests/ "
    }

    // Add common options
    pytestCmd += "-v --strict-markers "
    pytestCmd += "--junitxml=${config.reportDir}/python-results.xml "
    pytestCmd += "--html=${config.reportDir}/python-report.html "

    if (config.parallel) {
        pytestCmd += "-n auto "
    }

    if (config.markers) {
        pytestCmd += "-m '${config.markers}' "
    }

    // Set environment variables
    withEnv([
        "TEST_ENV=${config.environment}",
        "PYTHONPATH=${env.WORKSPACE}/src:${env.WORKSPACE}/tests"
    ]) {
        sh pytestCmd
    }

    return config.reportDir
}

/**
 * Setup test environment
 */
def setupTestEnvironment(String environment) {
    echo "Setting up ${environment} test environment"

    // Copy configuration files
    sh "cp src/test/resources/config-${environment}.properties src/test/resources/config.properties"

    // Create necessary directories
    sh '''
        mkdir -p target/screenshots
        mkdir -p target/logs
        mkdir -p reports
        mkdir -p allure-results
    '''

    // Environment-specific setup
    switch(environment) {
        case 'dev':
            sh 'echo "DEV environment setup complete"'
            break
        case 'qa':
            sh 'echo "QA environment setup complete"'
            break
        case 'staging':
            sh 'echo "Staging environment setup complete"'
            break
    }
}

/**
 * Generate comprehensive test reports
 */
def generateTestReports(String language, Map params = [:]) {
    def defaults = [
        generateAllure: true,
        archiveArtifacts: true
    ]

    def config = defaults + params

    echo "Generating ${language} test reports"

    // Process JUnit reports
    junit '**/reports/**/*.xml'

    // Generate Allure reports
    if (config.generateAllure && fileExists('allure-results')) {
        allure([
            includeProperties: false,
            reportBuildPolicy: 'ALWAYS',
            results: [[path: 'allure-results']]
        ])
    }

    // Archive artifacts
    if (config.archiveArtifacts) {
        archiveArtifacts artifacts: '**/reports/**/*.html, **/screenshots/*.png, **/logs/*.log', 
                        allowEmptyArchive: true
    }
}

/**
 * Send test execution notifications
 */
def sendTestNotification(String status, Map buildInfo) {
    def subject = "${status}: Test Execution - ${buildInfo.project} Build ${buildInfo.number}"

    def body = """
    <h2>Test Execution ${status}</h2>
    <p><strong>Project:</strong> ${buildInfo.project}</p>
    <p><strong>Build Number:</strong> ${buildInfo.number}</p>
    <p><strong>Duration:</strong> ${buildInfo.duration}</p>
    <p><strong>Environment:</strong> ${buildInfo.environment}</p>
    <p><a href="${buildInfo.url}">View Build Details</a></p>
    """

    emailext (
        subject: subject,
        body: body,
        to: 'qa-team@company.com'
    )
}

