                        results: [[path: 'allure-results']]
                    ])
                }
            }
        }
    }
}

/**
 * Template for cross-language end-to-end testing
 */
def crossLanguageE2EPipeline(Map config = [:]) {
    def defaults = [
        environments: ['qa', 'staging'],
        browsers: ['chrome', 'firefox'],
        parallel: true
    ]

    def finalConfig = defaults + config

    pipeline {
        agent any

        parameters {
            choice(
                name: 'TARGET_ENV',
                choices: finalConfig.environments,
                description: 'Target environment for E2E tests'
            )
        }

        stages {
            stage('Multi-Environment Setup') {
                steps {
                    script {
                        echo "Setting up ${params.TARGET_ENV} environment"

                        // Java setup
                        sh 'mvn dependency:resolve'

                        // Python setup
                        sh 'pip install -r requirements.txt'

                        // Environment config
                        sh "cp config-${params.TARGET_ENV}.properties config.properties"
                    }
                }
            }

            stage('Cross-Browser E2E Tests') {
                when {
                    expression { finalConfig.parallel }
                }
                parallel {
                    stage('Java E2E - Chrome') {
                        steps {
                            sh 'mvn test -Dgroups=e2e -Dbrowser=chrome -Denvironment=${params.TARGET_ENV}'
                        }
                    }

                    stage('Java E2E - Firefox') {
                        steps {
                            sh 'mvn test -Dgroups=e2e -Dbrowser=firefox -Denvironment=${params.TARGET_ENV}'
                        }
                    }

                    stage('Python E2E - Chrome') {
                        steps {
                            sh 'pytest tests/e2e/ -v --browser=chrome --environment=${params.TARGET_ENV}'
                        }
                    }

                    stage('Python E2E - Firefox') {
                        steps {
                            sh 'pytest tests/e2e/ -v --browser=firefox --environment=${params.TARGET_ENV}'
                        }
                    }
                }
            }

            stage('Sequential E2E Tests') {
                when {
                    expression { !finalConfig.parallel }
                }
                steps {
                    sh 'mvn test -Dgroups=e2e -Denvironment=${params.TARGET_ENV}'
                    sh 'pytest tests/e2e/ -v --environment=${params.TARGET_ENV}'
                }
            }
        }

        post {
            always {
                junit '**/reports/**/*.xml'
                archiveArtifacts artifacts: '**/screenshots/*.png, **/logs/*.log', allowEmptyArchive: true

                // Performance metrics
                sh 'python scripts/collect_performance_metrics.py'
            }
        }
    }
}

