        CURRENT_COLOR = sh(script: 'kubectl get service/app-service -o jsonpath="{.spec.selector.color}"', returnStdout: true).trim()
        NEW_COLOR = CURRENT_COLOR == 'blue' ? 'green' : 'blue'
    }
