            steps {
                script {
                    def testUrl = "http://app-${NEW_COLOR}.internal.company.com"
                    def response = httpRequest url: "${testUrl}/health", timeout: 60
                    if (response.status != 200) {
                        error "Smoke tests failed for ${NEW_COLOR} environment"
                    }
                    // Run comprehensive test suite
                    sh "npm run test:production -- --baseUrl=${testUrl}"
                }
            }
        }
        stage('Switch Traffic') {
            steps {
                sh """
                kubectl patch service app-service -p '{"spec":{"selector":{"color":"${NEW_COLOR}"}}}'
                """
            }
        }
        stage('Verify Live Traffic') {
            steps {
                sleep time: 60, unit: 'SECONDS'
                script {
                    def metrics = httpRequest url: 'http://monitoring/api/error-rate', contentType: 'APPLICATION_JSON'
                    if (parseJson(metrics.content).error_rate > 0.01) {
                        error "High error rate detected after traffic switch"
                    }
