// Custom Cucumber Plugin for Enhanced Reporting
public class CustomCucumberReporter implements ConcurrentEventListener {
    private final List<Map<String, Object>> featureMaps = new ArrayList<>();
    private final String buildNumber = System.getenv("BUILD_NUMBER");

    @Override
    public void setEventPublisher(EventPublisher publisher) {
        publisher.registerHandlerFor(TestRunFinished.class, this::handleTestRunFinished);
        publisher.registerHandlerFor(TestCaseFinished.class, this::handleTestCaseFinished);
    }

    private void handleTestCaseFinished(TestCaseFinished event) {
        // Capture detailed test case information
        Map<String, Object> testCaseInfo = new HashMap<>();
        testCaseInfo.put("name", event.getTestCase().getName());
        testCaseInfo.put("status", event.getResult().getStatus().toString());
        testCaseInfo.put("duration", event.getResult().getDuration().toNanos());
        testCaseInfo.put("build", buildNumber);

        // Add to feature maps for aggregation
        featureMaps.add(testCaseInfo);
    }

    private void handleTestRunFinished(TestRunFinished event) {
        // Generate custom report
        try {
            ObjectMapper mapper = new ObjectMapper();
            String customReport = mapper.writerWithDefaultPrettyPrinter()
                .writeValueAsString(featureMaps);

            // Write custom report
            Files.write(Paths.get("target/custom-cucumber-report.json"), 
                customReport.getBytes());

            // Generate metrics for dashboard
            generateMetricsReport();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void generateMetricsReport() {
        long totalDuration = featureMaps.stream()
            .mapToLong(m -> (Long) m.get("duration"))
            .sum();
        long passedTests = featureMaps.stream()
            .filter(m -> "PASSED".equals(m.get("status")))
            .count();

        Map<String, Object> metrics = new HashMap<>();
        metrics.put("total_tests", featureMaps.size());
        metrics.put("passed_tests", passedTests);
        metrics.put("success_rate", (double) passedTests / featureMaps.size());
        metrics.put("total_duration_ns", totalDuration);
        metrics.put("build_number", buildNumber);
        metrics.put("timestamp", Instant.now().toString());

        // Write metrics to file for Grafana
        try {
            ObjectMapper mapper = new ObjectMapper();
            Files.write(Paths.get("target/cucumber-metrics.json"), 
                mapper.writeValueAsBytes(metrics));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

