// Helper methods for test analytics
def analyzeTestTrends() {
    def trends = [:]

    // Get historical test data
    def buildHistory = getBuildHistory(30) // Last 30 builds

    trends.success_rate = buildHistory.collect { build ->
        build.testResults ? (build.testResults.passed / build.testResults.total * 100) : 0
    }

    trends.duration_trend = buildHistory.collect { build ->
        build.duration / 1000 // Convert to seconds
    }

    trends.test_count_trend = buildHistory.collect { build ->
        build.testResults?.total ?: 0
    }

    return trends
}

def calculateQualityMetrics() {
    def metrics = [:]

    // Calculate various quality metrics
    def testResult = currentBuild.rawBuild.getAction(hudson.tasks.junit.TestResultAction.class)
    if (testResult) {
        metrics.test_coverage = calculateTestCoverage()
        metrics.code_complexity = analyzeCodeComplexity()
        metrics.defect_density = calculateDefectDensity()
        metrics.mean_time_to_detect = calculateMTTD()
        metrics.mean_time_to_recover = calculateMTTR()
    }

    return metrics
}

def detectFlakyTests() {
    def flakyTests = []

    // Analyze test history for flaky patterns
    def testHistory = getTestHistory()

    testHistory.each { testName, history ->
        def passCount = history.count { it == 'PASSED' }
        def failCount = history.count { it == 'FAILED' }

        if (passCount > 0 && failCount > 0) {
            def flakinessScore = (failCount.toDouble() / (passCount + failCount)) * 100
            if (flakinessScore > 10) { // More than 10% failure rate
                flakyTests.add([
                    test_name: testName,
                    flakiness_score: flakinessScore,
                    total_runs: passCount + failCount,
                    failure_count: failCount
                ])
            }
        }
    }

    return flakyTests.sort { -it.flakiness_score }
}

#!/usr/bin/env python3
# test_metrics_analyzer.py - Advanced test metrics analysis

import json
import statistics
from datetime import datetime, timedelta
from collections import defaultdict

class TestMetricsAnalyzer:
    def __init__(self, build_data):
        self.build_data = build_data
        self.metrics = {}

    def calculate_trend_metrics(self):
        """Calculate trend-based metrics for test analysis"""
        success_rates = []
        durations = []
        test_counts = []

        for build in self.build_data:
            if build.get('test_results'):
                total = build['test_results']['total']
                passed = build['test_results']['passed']
                success_rates.append((passed / total) * 100)
                durations.append(build['duration'])
                test_counts.append(total)

        self.metrics['avg_success_rate'] = statistics.mean(success_rates)
        self.metrics['success_rate_trend'] = self._calculate_trend(success_rates)
        self.metrics['avg_duration'] = statistics.mean(durations)
        self.metrics['duration_trend'] = self._calculate_trend(durations)
        self.metrics['test_growth_rate'] = self._calculate_growth_rate(test_counts)

        return self.metrics

    def identify_flaky_tests(self, threshold=15):
        """Identify flaky tests based on historical failure patterns"""
        test_history = defaultdict(list)

        # Collect test execution history
        for build in self.build_data:
            if build.get('test_details'):
                for test in build['test_details']:
                    test_history[test['name']].append(test['status'])

        flaky_tests = []
        for test_name, history in test_history.items():
            if len(history) >= 5:  # Only consider tests with sufficient history
                pass_count = history.count('PASSED')
                fail_count = history.count('FAILED')
                total_runs = len(history)

                if fail_count > 0:
                    flakiness_percentage = (fail_count / total_runs) * 100
                    if flakiness_percentage >= threshold:
                        flaky_tests.append({
                            'test_name': test_name,
                            'flakiness_percentage': flakiness_percentage,
                            'total_runs': total_runs,
                            'failure_count': fail_count,
                            'last_failure': self._get_last_failure_date(test_name)
                        })

        return sorted(flaky_tests, key=lambda x: x['flakiness_percentage'], reverse=True)

    def generate_quality_report(self):
        """Generate comprehensive quality assessment report"""
        report = {
            'timestamp': datetime.now().isoformat(),
            'summary': {
                'total_builds_analyzed': len(self.build_data),
                'analysis_period': self._get_analysis_period(),
                'overall_health_score': self._calculate_health_score()
            },
            'trends': self.metrics,
            'flaky_tests': self.identify_flaky_tests(),
            'recommendations': self._generate_recommendations()
        }

        return report

    def _calculate_trend(self, data):
        """Calculate trend direction from data series"""
        if len(data) < 2:
            return 'stable'

        # Simple linear trend calculation
        first_half = statistics.mean(data[:len(data)//2])
        second_half = statistics.mean(data[len(data)//2:])

        if second_half > first_half * 1.05:
            return 'improving'
        elif second_half < first_half * 0.95:
            return 'deteriorating'
        else:
            return 'stable'

    def _calculate_growth_rate(self, data):
        """Calculate growth rate of test counts"""
        if len(data) < 2:
            return 0

        return ((data[-1] - data[0]) / data[0]) * 100

    def _calculate_health_score(self):
        """Calculate overall test health score (0-100)"""
        score = 100

        # Penalize for low success rates
        if self.metrics['avg_success_rate'] < 95:
            score -= (95 - self.metrics['avg_success_rate']) * 2

        # Penalize for deteriorating trends
        if self.metrics['success_rate_trend'] == 'deteriorating':
            score -= 10

        # Penalize for flaky tests
        flaky_tests = self.identify_flaky_tests()
        if flaky_tests:
            score -= min(20, len(flaky_tests) * 2)

        return max(0, score)

    def _generate_recommendations(self):
        """Generate actionable recommendations based on analysis"""
        recommendations = []

        if self.metrics['avg_success_rate'] < 90:
            recommendations.append({
                'priority': 'high',
                'action': 'Investigate and fix failing tests',
                'reason': f'Success rate ({self.metrics["avg_success_rate"]:.1f}%) below 90% threshold'
            })

        flaky_tests = self.identify_flaky_tests()
        if flaky_tests:
            recommendations.append({
                'priority': 'medium',
                'action': 'Address flaky tests',
                'reason': f'Found {len(flaky_tests)} tests with flaky behavior'
            })

        if self.metrics['success_rate_trend'] == 'deteriorating':
            recommendations.append({
                'priority': 'high',
                'action': 'Analyze recent changes causing test degradation',
                'reason': 'Test success rate shows deteriorating trend'
            })

        return recommendations

# Usage example
if __name__ == "__main__":
    # Load build data from Jenkins API or files
    with open('build-history.json') as f:
        build_data = json.load(f)

    analyzer = TestMetricsAnalyzer(build_data)
    analyzer.calculate_trend_metrics()
    report = analyzer.generate_quality_report()

    # Save comprehensive report
    with open('quality-assessment.json', 'w') as f:
        json.dump(report, f, indent=2)

    print(f"Quality assessment completed. Health score: {report['summary']['overall_health_score']}")

