                def testSummary = generateTestSummary()
                env.TEST_SUMMARY = testSummary

                // Determine email template based on results
                def emailTemplate = getEmailTemplate(currentBuild.currentResult, testSummary)

                // Send email notification
                emailext(
                    to: env.EMAIL_RECIPIENTS,
                    subject: "${env.JOB_NAME} - Build #${env.BUILD_NUMBER} - ${currentBuild.currentResult}",
                    body: emailTemplate,
                    mimeType: 'text/html',
                    attachLog: true,
                    compressLog: true,
                    attachmentsPattern: '**/test-results/**/*.html, **/reports/**/*.pdf'
                )
            }
        }
        success {
            script {
                // Success notification with additional details
                emailext(
                    to: env.EMAIL_RECIPIENTS,
                    subject: "✅ SUCCESS: ${env.JOB_NAME} Build #${env.BUILD_NUMBER}",
                    body: generateSuccessEmail(),
                    mimeType: 'text/html'
                )
            }
        }
        failure {
            script {
                // Failure notification with failure analysis
                emailext(
                    to: env.EMAIL_RECIPIENTS,
                    subject: "❌ FAILURE: ${env.JOB_NAME} Build #${env.BUILD_NUMBER}",
                    body: generateFailureEmail(),
                    mimeType: 'text/html',
                    attachLog: true
                )

                // Critical failure escalation
                if (isCriticalFailure()) {
                    emailext(
                        to: env.EMAIL_CRITICAL,
                        subject: "🚨 CRITICAL FAILURE: ${env.JOB_NAME} Build #${env.BUILD_NUMBER}",
                        body: generateCriticalFailureEmail(),
                        mimeType: 'text/html'
                    )
                }
            }
        }
        unstable {
            script {
                // Unstable build notification
                emailext(
                    to: env.EMAIL_RECIPIENTS,
                    subject: "⚠️ UNSTABLE: ${env.JOB_NAME} Build #${env.BUILD_NUMBER}",
                    body: generateUnstableEmail(),
                    mimeType: 'text/html'
                )
            }
        }
        changed {
            script {
                // Notification when build status changes
                if (currentBuild.currentResult == 'SUCCESS') {
                    emailext(
                        to: env.EMAIL_RECIPIENTS,
                        subject: "🔄 RECOVERED: ${env.JOB_NAME} Build #${env.BUILD_NUMBER}",
                        body: generateRecoveryEmail(),
                        mimeType: 'text/html'
                    )
                }
            }
        }
    }
}

