// RBAC helper methods
def getUserPermissions() {
    def user = env.BUILD_USER_ID ?: 'anonymous'
    def userGroups = getUserGroups(user)
    def permissions = []

    // Map user groups to permissions
    def rolePermissions = [
        'admin': ['read', 'write', 'execute', 'configure', 'security-scan', 'production-deploy'],
        'developer': ['read', 'write', 'execute', 'security-scan'],
        'qa-engineer': ['read', 'execute', 'security-scan'],
        'viewer': ['read'],
        'prod-engineer': ['read', 'execute', 'production-deploy']
    ]

    userGroups.each { group ->
        permissions.addAll(rolePermissions.get(group, []))
    }

    return permissions.unique()
}

def hasEnvironmentAccess(String environment) {
    def userPermissions = getUserPermissions()

    switch(environment) {
        case 'dev':
            return userPermissions.contains('execute')
        case 'qa':
            return userPermissions.contains('execute')
        case 'staging':
            return userPermissions.contains('execute') && userPermissions.contains('security-scan')
        case 'production':
            return userPermissions.contains('production-deploy')
        default:
            return false
    }
}

