pipeline {
    agent none // Use specific agents for each stage

    options {
        timeout(time: 20, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '20'))
        skipDefaultCheckout() // Checkout only when needed
    }

    environment {
        // Cache configuration
        MAVEN_OPTS = '-Dmaven.repo.local=/tmp/m2repo -Xmx2g'
        NPM_CONFIG_CACHE = '/tmp/npm-cache'

        // Performance tuning
        GRADLE_OPTS = '-Dorg.gradle.parallel=true -Dorg.gradle.caching=true'
        MAVEN_THREADS = '4'
    }

    stages {
        stage('Checkout & Setup') {
            agent {
                kubernetes {
                    label 'small-agent'
                    yaml '''
                        spec:
                          containers:
                          - name: git
                            image: alpine/git:latest
                            resources:
                              requests:
                                memory: "256Mi"
                                cpu: "100m"
                    '''
                }
            }
            steps {
                // ✅ OPTIMIZED: Minimal checkout with sparse checkout if possible
                checkout([
                    $class: 'GitSCM',
                    branches: [[name: env.GIT_COMMIT]],
                    extensions: [
                        [$class: 'SparseCheckoutPaths', 
                         sparseCheckoutPaths: [[path: 'src/'], [path: 'pom.xml']]]
                    ],
                    userRemoteConfigs: [[url: env.GIT_URL]]
                ])

                // ✅ OPTIMIZED: Restore dependency cache
                sh '''
                    # Restore Maven dependencies from cache
                    if [ -f "/cache/m2repo.tar.gz" ]; then
                        tar -xzf /cache/m2repo.tar.gz -C /tmp/
                    fi

                    # Restore npm cache
                    if [ -f "/cache/npm-cache.tar.gz" ]; then
                        tar -xzf /cache/npm-cache.tar.gz -C /tmp/
                    fi
                '''
            }
        }

        stage('Parallel Quality Checks') {
            // ✅ OPTIMIZED: Parallel execution of independent quality checks
            parallel {
                stage('Static Analysis') {
                    agent { label 'medium-agent' }
                    steps {
                        script {
                            sh 'mvn sonar:sonar -Dsonar.coverage.exclusions="**/test/**"'
                        }
                    }
                }

                stage('Security Scan') {
                    agent { label 'medium-agent' }
                    steps {
                        script {
                            sh '''
                                # Fast security scans
                                npm audit --production
                                trivy filesystem --exit-code 1 --severity HIGH .
                            '''
                        }
                    }
                }

                stage('Code Style') {
                    agent { label 'small-agent' }
                    steps {
                        script {
                            sh '''
                                # Lightweight code style checks
                                mvn checkstyle:check
                                npx prettier --check "src/**/*.js"
                            '''
                        }
                    }
                }
            }
        }

        stage('Build & Unit Tests') {
            agent {
                kubernetes {
                    label 'large-agent'
                    yaml '''
                        spec:
                          containers:
                          - name: maven
                            image: maven:3.8-openjdk-11
                            resources:
                              requests:
                                memory: "4Gi"
                                cpu: "2"
                              limits:
                                memory: "8Gi"
                                cpu: "4"
                    '''
                }
            }
            steps {
                script {
